import re
import sys
from pathlib import Path

ONEPAGER_PATH = Path("positioning/midmarket-platform-devex-onepager.md")


def fail(msg: str) -> None:
    print(f"FAIL: {msg}")
    sys.exit(1)


def ok(msg: str) -> None:
    print(f"OK: {msg}")


def strip_code_blocks(md: str) -> str:
    return re.sub(r"```[\s\S]*?```", "", md)


def non_heading_word_count(md: str) -> int:
    md = strip_code_blocks(md)
    lines = md.splitlines()
    non_heading = [ln for ln in lines if not re.match(r"^\s*#{1,6}\s+", ln)]
    text = "\n".join(non_heading)
    # Only count ASCII words/numbers for a stable, conservative verifier.
    return len(re.findall(r"\b[0-9A-Za-z]+\b", text))


def require_section(md: str, heading: str) -> str:
    pattern = re.compile(
        rf"^##\s+{re.escape(heading)}\s*$([\s\S]*?)(?=^##\s+|\Z)",
        re.MULTILINE,
    )
    m = pattern.search(md)
    if not m:
        fail(f"Missing section '## {heading}'")
    return m.group(1).strip("\n")


def count_objection_pairs(section_body: str) -> int:
    lines = [ln.strip() for ln in section_body.splitlines() if ln.strip()]
    return sum(1 for ln in lines if re.match(r"^\d+\)\s+\*\*.+\*\*", ln))


def main() -> None:
    if not ONEPAGER_PATH.exists():
        fail(f"Missing required one-pager at {ONEPAGER_PATH.as_posix()}")

    md = ONEPAGER_PATH.read_text(encoding="utf-8")

    wc = non_heading_word_count(md)
    if wc > 600:
        fail(f"Word count excluding headings is {wc} (> 600)")
    ok(f"Word count excluding headings: {wc} (<= 600)")

    seg = require_section(md, "Segment definition")
    if not re.search(r"Company size\s*\(mid-market\)", seg, re.IGNORECASE):
        fail("Segment definition must explicitly cover company size (mid-market)")
    if not re.search(r"Target buyer/user roles\s*\(Platform/DevEx\)", seg, re.IGNORECASE):
        fail("Segment definition must explicitly cover target buyer/user roles (Platform/DevEx)")
    if not re.search(r"\b200\s*[–-]\s*2,000\b", seg):
        fail("Segment definition should include 200–2,000 employee range")
    ok("Segment definition includes company size and Platform/DevEx roles")

    pos = require_section(md, "Positioning statement")
    pos_line = " ".join([ln.strip() for ln in pos.splitlines() if ln.strip()])
    form = re.compile(
        r"^For\s+.+\s+who\s+.+,\s*.+\s+is\s+a\s+.+\s+that\s+.+\s+unlike\s+.+\s+our\s+.+\.?$",
        re.IGNORECASE,
    )
    if not form.match(pos_line):
        fail(
            "Positioning statement must match: 'For <segment> who <need>, <product> is a <category> that <benefit> unlike <alternative> our <differentiator>'"
        )
    ok("Positioning statement matches required template")

    pillars = require_section(md, "Key value pillars (exactly 3)")
    pillar_blocks = re.split(r"^###\s+", pillars, flags=re.MULTILINE)
    pillar_blocks = [b for b in pillar_blocks[1:] if b.strip()]
    if len(pillar_blocks) != 3:
        fail(f"Expected exactly 3 value pillars (### headings), found {len(pillar_blocks)}")

    for i, blk in enumerate(pillar_blocks, start=1):
        if not re.search(r"^\*\*Benefit:\*\*\s+.+\.$", blk.strip(), re.MULTILINE):
            fail(
                f"Pillar {i} must include exactly one 1-sentence benefit line starting with '**Benefit:**' and ending with a period"
            )
        proof_lines = re.findall(r"^\-\s+\*\*Proof:\*\*\s+.+", blk, flags=re.MULTILINE)
        if len(proof_lines) != 2:
            fail(f"Pillar {i} must include exactly 2 proof point bullets; found {len(proof_lines)}")
    ok("Found exactly 3 pillars, each with 1 benefit sentence and 2 proof bullets")

    against = require_section(md, "Against alternatives")
    against_bullets = re.findall(r"^\-\s+.+", against, flags=re.MULTILINE)
    if len(against_bullets) < 3:
        fail(f"Against alternatives must include at least 3 bullet comparisons; found {len(against_bullets)}")
    ok("Against alternatives has >= 3 comparisons")

    obj = require_section(md, "Key objections & responses")
    pairs = count_objection_pairs(obj)
    if pairs < 5:
        fail(f"Expected at least 5 objection/response pairs; found {pairs}")
    ok("Key objections & responses has >= 5 pairs")

    dd = require_section(md, "Do/Don't messaging guidance")
    do_body = re.search(r"\*\*Do:\*\*([\s\S]*?)\*\*Don['’]t:\*\*", dd)
    if not do_body:
        fail("Do/Don't section must include '**Do:**' and '**Don't:**' subsections")
    do_text = do_body.group(1)
    dont_text = dd.split("**Don't:**", 1)[1] if "**Don't:**" in dd else ""

    do_bullets = re.findall(r"^\-\s+.+", do_text, flags=re.MULTILINE)
    dont_bullets = re.findall(r"^\-\s+.+", dont_text, flags=re.MULTILINE)
    if len(do_bullets) < 5:
        fail(f"Expected at least 5 Do bullets; found {len(do_bullets)}")
    if len(dont_bullets) < 5:
        fail(f"Expected at least 5 Don't bullets; found {len(dont_bullets)}")
    ok("Do/Don't messaging guidance has >= 5 Do and >= 5 Don't bullets")

    sample = require_section(md, "Sample messages")

    if not re.search(r"\*\*Homepage hero:\*\*\s+.+", sample):
        fail("Sample messages must include '**Homepage hero:**'")
    if not re.search(r"\*\*Subhead:\*\*\s+.+", sample):
        fail("Sample messages must include '**Subhead:**'")

    head_match = re.search(
        r"\*\*Ad headlines \(<= 50 chars\):\*\*([\s\S]*?)\*\*Ad descriptions \(<= 120 chars\):\*\*",
        sample,
    )
    if not head_match:
        fail("Sample messages must include 'Ad headlines' and 'Ad descriptions' subsections")
    heads_block = head_match.group(1)
    headlines = [
        re.sub(r"^\-\s+", "", ln.strip())
        for ln in heads_block.splitlines()
        if ln.strip().startswith("-")
    ]
    if len(headlines) != 3:
        fail(f"Expected exactly 3 ad headlines; found {len(headlines)}")
    for h in headlines:
        if len(h) > 50:
            fail(f"Ad headline too long ({len(h)} chars): {h}")

    desc_block = sample.split("**Ad descriptions (<= 120 chars):**", 1)
    if len(desc_block) != 2:
        fail("Missing '**Ad descriptions (<= 120 chars):**'")
    desc_text = desc_block[1]
    desc_text = re.split(r"\*\*Outbound email \(<= 120 words\):\*\*", desc_text)[0]
    descriptions = [
        re.sub(r"^\-\s+", "", ln.strip())
        for ln in desc_text.splitlines()
        if ln.strip().startswith("-")
    ]
    if len(descriptions) != 3:
        fail(f"Expected exactly 3 ad descriptions; found {len(descriptions)}")
    for d in descriptions:
        if len(d) > 120:
            fail(f"Ad description too long ({len(d)} chars): {d}")

    email_match = re.search(r"\*\*Outbound email \(<= 120 words\):\*\*([\s\S]*)\Z", sample)
    if not email_match:
        fail("Missing outbound email")
    email_text = email_match.group(1).strip()
    email_words = re.findall(r"\b\w+\b", email_text)
    if len(email_words) > 120:
        fail(f"Outbound email is {len(email_words)} words (> 120)")

    ok(
        "Sample messages includes hero, subhead, 3 headlines (<=50), 3 descriptions (<=120), and outbound email (<=120 words)"
    )

    cta = require_section(md, "CTA")
    cta_bullets = [ln for ln in cta.splitlines() if ln.strip().startswith("-")]
    if len(cta_bullets) != 2:
        fail(
            f"CTA section must list exactly 2 primary calls-to-action (bullets); found {len(cta_bullets)}"
        )
    ok("CTA section has exactly 2 bullets")

    print("\nAll checks passed.")


if __name__ == "__main__":
    main()

import json
import re
import sys
from pathlib import Path

PLAYBOOK_MD = Path("playbooks/midmarket-platform-devex-inbound.md")
CHECKLIST_JSON = Path("playbooks/midmarket-platform-devex-inbound.checklist.json")

REQUIRED_SECTIONS = [
    "## ICP (Ideal Customer Profile): Mid-market Platform/DevEx inbound",
    "## Qualification checklist (Yes/No)",
    "## Lead scoring rubric (points + thresholds)",
    "## Disqualification (hard \u201cno\u201d) signals + next action",
    "## Intake questions (Discovery) \u2014 required for inbound qualification",
    "## Good fit vs bad fit (examples)",
    "## Outbound-to-inbound handoff (fields + routing owners)",
]


def fail(msg: str) -> None:
    print(f"FAIL: {msg}")
    sys.exit(1)


def count_numbered_items_in_section(md: str, section_heading_regex: str) -> int:
    m = re.search(section_heading_regex, md, flags=re.S)
    if not m:
        return 0
    block = m.group(1)
    return len(re.findall(r"^\s*\d+\.\s+.+", block, flags=re.M))


def count_examples(md: str, heading: str) -> int:
    pat = rf"{re.escape(heading)}\n(.*?)(?:\n###\s+|\n---\n|\n##\s+)"
    m = re.search(pat, md, flags=re.S)
    if not m:
        return 0
    block = m.group(1)
    return len(re.findall(r"^\s*\d+\.\s+.+", block, flags=re.M))


def main() -> None:
    if not PLAYBOOK_MD.exists():
        fail(f"Missing playbook markdown: {PLAYBOOK_MD}")
    if not CHECKLIST_JSON.exists():
        fail(f"Missing checklist JSON: {CHECKLIST_JSON}")

    md = PLAYBOOK_MD.read_text(encoding="utf-8")

    for sec in REQUIRED_SECTIONS:
        if sec not in md:
            fail(f"Missing required section heading: {sec}")

    # ICP details: employee range + technographics + buying roles must be present
    if not re.search(r"Employee range \(target\):\s*\*\*?\s*200\s*[-\u2013]\s*2,000", md):
        fail("ICP firmographics missing employee range 200-2,000")
    if "### Technographics" not in md:
        fail("ICP technographics section missing")
    if "### Buying committee & roles" not in md:
        fail("ICP buying committee roles section missing")

    yesno_count = count_numbered_items_in_section(
        md, r"## Qualification checklist \(Yes/No\)(.*?)(?:\n---\n)"
    )
    if yesno_count < 15:
        fail(f"Qualification checklist must have at least 15 yes/no questions; found {yesno_count}")

    disq_count = count_numbered_items_in_section(
        md, r"## Disqualification \(hard .*?\) signals \+ next action(.*?)(?:\n---\n)"
    )
    if disq_count < 10:
        fail(f"Disqualification must list at least 10 signals; found {disq_count}")

    intake_count = count_numbered_items_in_section(
        md,
        r"## Intake questions \(Discovery\) .*?required for inbound qualification(.*?)(?:\n---\n)",
    )
    if intake_count < 12:
        fail(f"Intake questions must have at least 12 questions; found {intake_count}")

    good_examples = count_examples(md, "### Good fit examples")
    bad_examples = count_examples(md, "### Bad fit examples")
    if good_examples < 3:
        fail(f"Good fit examples must be at least 3; found {good_examples}")
    if bad_examples < 3:
        fail(f"Bad fit examples must be at least 3; found {bad_examples}")

    # JSON validity + mirror constraints
    data = json.loads(CHECKLIST_JSON.read_text(encoding="utf-8"))

    questions = data.get("checklist", {}).get("questions", [])
    if len(questions) < 15:
        fail(f"Checklist JSON must have at least 15 questions; found {len(questions)}")

    thresholds = data.get("scoring", {}).get("thresholds", {})
    sqo = thresholds.get("sqo_min_points")
    nurture = thresholds.get("nurture_min_points")
    if not isinstance(sqo, int) or not isinstance(nurture, int):
        fail("Checklist JSON scoring.thresholds must include integer sqo_min_points and nurture_min_points")
    if sqo <= nurture:
        fail("sqo_min_points must be greater than nurture_min_points")

    disq = data.get("disqualifiers", {}).get("signals", [])
    if len(disq) < 10:
        fail(f"Checklist JSON must have at least 10 disqualifiers; found {len(disq)}")

    print("PASS: playbook and checklist meet minimum requirements")


if __name__ == "__main__":
    main()

