import json
import re
import sys
from pathlib import Path

MD_PATH = Path("playbooks/midmarket_platform_devex_inbound_checklist.md")
JSON_PATH = Path("playbooks/midmarket_platform_devex_inbound_checklist.json")

REQUIRED_MD_SECTIONS = [
    r"^## ICP \(Ideal Customer Profile\)",
    r"^## Intake data requirements \(capture fields \+ mandatory flags\)",
    r"^## Qualification checklist \(numbered questions \+ pass/fail guidance\)",
    r"^## Lead scoring rubric \(weighted points \+ thresholds\)",
    r"^## Disqualification \(hard .*no-go.*\)",
    r"^## Discovery call script \(inbound\)",
    r"^## Objection handling \(Platform/DevEx\)",
    r"^## Persona-specific qualification variations",
]


def fail(msg: str) -> None:
    print(f"FAIL: {msg}")
    sys.exit(1)


def must_exist() -> None:
    if not MD_PATH.exists():
        fail(f"Missing required file: {MD_PATH}")
    if not JSON_PATH.exists():
        fail(f"Missing required file: {JSON_PATH}")


def verify_markdown() -> None:
    txt = MD_PATH.read_text(encoding="utf-8")

    # Required sections
    for pattern in REQUIRED_MD_SECTIONS:
        if re.search(pattern, txt, flags=re.MULTILINE) is None:
            fail(f"Markdown missing required section heading matching: {pattern}")

    # Numbered checklist questions: at least 10 occurrences like '1.' at start of line
    numbered = re.findall(r"^\d+\.\s+", txt, flags=re.MULTILINE)
    if len(numbered) < 10:
        fail(f"Markdown needs a numbered list of qualifying questions; found {len(numbered)} numbered items")

    # Disqualifiers: at least 5 hard no-go conditions
    disq_section = re.search(r"^## Disqualification[\s\S]*?(?=^## |\Z)", txt, flags=re.MULTILINE)
    if not disq_section:
        fail("Could not locate Disqualification section")
    disq_bullets = re.findall(r"^\d+\.\s+|^-\s+", disq_section.group(0), flags=re.MULTILINE)
    if len(disq_bullets) < 5:
        fail(f"Disqualification section must list at least 5 conditions; found {len(disq_bullets)}")

    # Objections: at least 5
    obj_section = re.search(r"^## Objection handling[\s\S]*?(?=^## |\Z)", txt, flags=re.MULTILINE)
    if not obj_section:
        fail("Could not locate Objection handling section")
    obj_numbered = re.findall(r"^\d+\.\s+", obj_section.group(0), flags=re.MULTILINE)
    if len(obj_numbered) < 5:
        fail(f"Objection handling must cover at least 5 objections; found {len(obj_numbered)}")

    # Personas: at least 3
    persona_section = re.search(r"^## Persona-specific qualification variations[\s\S]*?(?=^## |\Z)", txt, flags=re.MULTILINE)
    if not persona_section:
        fail("Could not locate Persona-specific qualification variations section")
    persona_headers = re.findall(r"^###\s+", persona_section.group(0), flags=re.MULTILINE)
    if len(persona_headers) < 3:
        fail(f"Need at least 3 persona-specific variations; found {len(persona_headers)}")


def verify_json() -> None:
    try:
        data = json.loads(JSON_PATH.read_text(encoding="utf-8"))
    except Exception as e:
        fail(f"Checklist JSON is not valid JSON: {e}")

    # Required top-level keys
    for k in ["name", "version", "icp", "intake_fields", "questions", "scoring", "disqualifiers", "personas"]:
        if k not in data:
            fail(f"JSON missing required top-level key: {k}")

    # Questions
    if not isinstance(data["questions"], list) or len(data["questions"]) < 5:
        fail("JSON must contain at least 5 questions")
    for q in data["questions"]:
        for k in ["id", "text", "evidence_sources", "pass_guidance", "fail_guidance"]:
            if k not in q:
                fail(f"Question missing key '{k}': {q}")

    # Scoring rubric
    scoring = data["scoring"]
    if "criteria" not in scoring or not isinstance(scoring["criteria"], list) or len(scoring["criteria"]) < 5:
        fail("JSON scoring.criteria must be a list with at least 5 criteria")
    for c in scoring["criteria"]:
        for k in ["id", "name", "weight", "levels"]:
            if k not in c:
                fail(f"Scoring criterion missing key '{k}': {c}")
    if "thresholds" not in scoring:
        fail("JSON scoring missing thresholds")
    for k in ["sales_qualified_min", "nurture_min", "disqualify_max"]:
        if k not in scoring["thresholds"]:
            fail(f"JSON scoring.thresholds missing key: {k}")


def main() -> None:
    must_exist()
    verify_markdown()
    verify_json()
    print("PASS: mid-market Platform/DevEx inbound playbook artifacts verified")


if __name__ == "__main__":
    main()

